// This file owns post-run flag-correction derivation: turning an
// observed "failed flag, then same-session corrected retry" journal
// sequence into an open flag_alias candidate. Derivation is read-only
// against the journal (it never appends entries) and write-only
// against the quarantined candidate store — nothing here touches the
// verified learning rows.

// flagCorrectionWindow bounds how long after a failed flag its
// correcting success may arrive and still pair. A time window is used
// rather than an entry-count window because the journal interleaves
// sessions: a busy foreign session could push an honest correction out
// of any fixed entry budget, while wall-clock distance is
// session-independent. The same window decides when an unpaired
// failure stops being "pending" (see DeriveFlagCorrections).
const flagCorrectionWindow = 15 * time.Minute

// Polls cover a peer that is already near the end of its pass. The
// blocking acquire runs only after that, and only when complete journal
// lines are still unread: this command may have appended the correction
// that the peer's scan missed, and no later command is guaranteed.
const (
	deriveLockPolls   = 5
	deriveLockPollGap = 20 * time.Millisecond
	// A peer can append while this process holds the lock. Drain those
	// lines before unlocking so the peer's failed try-lock does not
	// orphan them. The cap keeps a tight append loop from holding the
	// post-run hook open.
	deriveDrainLimit = 8
)

// CandidateStore is the narrow slice of the candidate store the
// derivation pass needs. *store.Store satisfies it; the indirection
// keeps derivation testable against the real SQLite store without the
// pass owning open/close policy beyond its own lazy handle.
type CandidateStore interface {
	CommitFlagCorrections(items []store.FlagCorrectionSighting, batchStart, batchEnd store.JournalCursor) (store.FlagCorrectionCommit, error)
	Close() error
}

// flagCorrection is one paired observation ready to become a
// flag_alias candidate.
type flagCorrection struct {
	CommandPath   string
	FailedFlag    string
	CorrectedFlag string
	Example       string
	QueryFamily   string
}

// flagAliasDerivedPayload is the candidate payload contract for
// derived flag corrections. Example is a sanitized invocation string —
// verb chain plus flag names only, never values.
type flagAliasDerivedPayload struct {
	CommandPath   string `json:"command_path,omitempty"`
	FailedFlag    string `json:"failed_flag"`
	CorrectedFlag string `json:"corrected_flag"`
	Example       string `json:"example,omitempty"`
}

// DeriveFlagCorrections runs one bounded tail scan of the invocation
// journal from the persisted (segment, byte) offset and records every
// paired flag correction as a flag_alias candidate observation. The
// file offset marks how far a pass has read and advances only after
// that pass finishes, so a failed pass cannot skip entries it did not
// commit. Re-reading a batch that was already committed does not bump
// sightings; the cursor stored with those sightings decides.
//
// Pairing rule — ALL required:
//   - same session key;
//   - same subcommand verb chain;
//   - the success (exit 0) is the NEXT invocation of that command in
//     that session, within flagCorrectionWindow of the failure;
//   - the failed flag resolves to no real flag anywhere in the command
//     tree (flagExists probes the whole tree, dashes stripped);
//   - when the journal has a did-you-mean suggestion, that suggestion
//     names the correction and appears in the success entry's argv
//     shape;
//   - when no suggestion was recorded, the correction is the one new
//     success-entry flag absent from the failed entry's argv shape, or
//     the closest such flag by edit distance when multiple were added;
//     ties are skipped rather than guessed.
//
// Batches are consumed atomically. When the tail still holds an
// unpaired failure fresh enough to pair (its correction may not be
// journaled yet), the pass derives nothing and keeps the offset, so
// the batch is reprocessed whole on the next post-run pass. Once the
// failure ages past the window it is decided (no pair) and the offset
// moves on.
//
// Sightings and the consumed cursor commit together. The file cursor
// is only a read position: if it lags the stored cursor (a crash after
// the commit, or a second process that read the same offset), the
// stored cursor is authoritative and the overlapping prefix is not
// counted again. A stored cursor strictly inside a re-read window
// resumes the pass after that cursor.
//
// The store opener is lazy: SQLite is touched only when the pass
// actually paired something, so framework-only invocations never
// create the learn database from this path.
func DeriveFlagCorrections(openStore func() (CandidateStore, error), flagExists func(name string) bool) error {
	if JournalCaptureDisabled() {
		return nil
	}
	dir, err := JournalDir()
	if err != nil {
		return err
	}
	// Uncontended, and any pass whose tail a peer has already consumed,
	// returns without waiting. Waiting on every exit stalled commands
	// that had nothing left to derive. A still-unread tail cannot take
	// that fast path: the line may be the correction this command just
	// appended, and skipping it would leave the pair unprocessed.
	path := filepath.Join(dir, journalOffsetFileName)
	for poll := 0; ; poll++ {
		acquired, lockErr := cliutil.TryWithFileLock(path, func() error {
			return deriveFlagCorrectionsUntilStable(openStore, flagExists)
		})
		if lockErr != nil {
			return lockErr
		}
		if acquired {
			return nil
		}
		unread, unreadErr := journalHasUnreadTail()
		if unreadErr != nil {
			return unreadErr
		}
		if !unread {
			return nil
		}
		if poll == deriveLockPolls-1 {
			return cliutil.WithFileLock(path, func() error {
				return deriveFlagCorrectionsUntilStable(openStore, flagExists)
			})
		}
		time.Sleep(deriveLockPollGap)
	}
}

// deriveFlagCorrectionsUntilStable drains journal lines that land while
// this process holds the offset lock. A peer that loses the try-lock
// will not scan them; leaving them until the next command drops a
// correction when that peer was the last invocation. The locked pass
// reports whether a complete line arrived after the cursor it consumed,
// so the segment is not loaded again on the way in and on the way out.
func deriveFlagCorrectionsUntilStable(openStore func() (CandidateStore, error), flagExists func(name string) bool) error {
	for i := 0; i < deriveDrainLimit; i++ {
		again, err := deriveFlagCorrectionsLocked(openStore, flagExists, false)
		if err != nil {
			return err
		}
		if !again {
			return nil
		}
	}
	return nil
}

// journalHasUnreadTail is the skip predicate. Complete lines past the
// file cursor still need a pass; a caught-up cursor means a peer
// already consumed this command's append and waiting would only stall.
func journalHasUnreadTail() (bool, error) {
	offset, err := LoadJournalOffset()
	if err != nil {
		return false, err
	}
	entries, next, err := ReadJournalFrom(offset)
	if err != nil {
		return false, err
	}
	return len(entries) > 0 || next != offset, nil
}

// deriveFlagCorrectionsLocked reports whether the caller should scan
// once more. A complete line past the cursor this pass consumed means
// an append landed while the lock was held and must be derived before
// unlock. A fresh unpaired failure reports false when its window did
// not grow, so the hook does not spin.
func deriveFlagCorrectionsLocked(openStore func() (CandidateStore, error), flagExists func(name string) bool, resumed bool) (bool, error) {
	offset, err := LoadJournalOffset()
	if err != nil {
		return false, err
	}
	// A cursor already at the segment tail has nothing to parse.
	// ReadJournalFrom would still load the whole segment.
	atTail, err := journalCursorAtTail(offset)
	if err != nil {
		return false, err
	}
	if atTail {
		return journalNewlinePast(offset)
	}
	entries, next, err := ReadJournalFrom(offset)
	if err != nil {
		return false, err
	}
	if len(entries) == 0 && next == offset {
		// Caught up, or only a torn tail. A complete line appended
		// after this read still has to be drained.
		return journalNewlinePast(offset)
	}
	recallSeed := sessionRecallFamiliesBeforeBatch(entries, offset)
	pairs, pending := pairFlagCorrections(entries, recallSeed, time.Now().UTC(), flagExists)
	if pending {
		// The unpaired failure stays unread on purpose. Loop only when
		// a complete line arrived after the window just read.
		return journalNewlinePast(next)
	}
	if len(pairs) == 0 {
		if err := StoreJournalOffset(next); err != nil {
			return false, err
		}
		return journalNewlinePast(next)
	}
	if openStore == nil {
		return false, fmt.Errorf("derive flag corrections: no candidate store opener")
	}
	items, err := flagCorrectionSightings(pairs)
	if err != nil {
		return false, err
	}
	cs, err := openStore()
	if err != nil {
		return false, fmt.Errorf("derive flag corrections: open store: %w", err)
	}
	result, err := cs.CommitFlagCorrections(items, journalCursor(offset), journalCursor(next))
	closeErr := cs.Close()
	if err != nil {
		// The cursor is not advanced: the batch replays next pass
		// rather than losing the observation. The commit is atomic, so
		// a failed pass leaves no partial sightings behind.
		return false, fmt.Errorf("derive flag corrections: %w", err)
	}
	if closeErr != nil {
		return false, fmt.Errorf("derive flag corrections: close store: %w", closeErr)
	}
	start := journalCursor(offset)
	end := journalCursor(next)
	if !result.Applied && start.Before(result.Resume) && result.Resume.Before(end) {
		// One resume consumes a cursor that landed inside this window.
		// A second one means the file cursor did not move; another
		// pass would spin the post-run hook.
		if resumed {
			return false, fmt.Errorf("derive flag corrections: journal cursor did not advance")
		}
		if err := StoreJournalOffset(journalOffset(result.Resume)); err != nil {
			return false, err
		}
		return deriveFlagCorrectionsLocked(openStore, flagExists, true)
	}
	if err := StoreJournalOffset(next); err != nil {
		return false, err
	}
	return journalNewlinePast(next)
}

// journalCursorAtTail reports whether reading offset would observe no
// further bytes and leave the cursor where it is. Older segments are
// ignored, matching ReadJournalFrom.
func journalCursorAtTail(offset JournalOffset) (bool, error) {
	if offset.Segment == "" {
		return false, nil
	}
	dir, err := JournalDir()
	if err != nil {
		return false, err
	}
	segs, err := listJournalSegments(dir)
	if err != nil {
		return false, err
	}
	found := false
	for _, s := range segs {
		if s.name > offset.Segment {
			return false, nil
		}
		if s.name == offset.Segment {
			found = true
			if s.size != offset.Byte {
				return false, nil
			}
		}
	}
	return found, nil
}

// journalNewlinePast reports whether a complete line exists past offset.
// The check reads only the unread suffix (and any newer segment), not
// the segment prefix the cursor has already consumed.
func journalNewlinePast(offset JournalOffset) (bool, error) {
	dir, err := JournalDir()
	if err != nil {
		return false, err
	}
	segs, err := listJournalSegments(dir)
	if err != nil {
		return false, err
	}
	startName, startByte := journalScanStart(segs, offset)
	for _, s := range segs {
		if startName != "" && s.name < startName {
			continue
		}
		from := int64(0)
		if s.name == startName {
			from = startByte
		}
		if from < 0 {
			from = 0
		}
		if from > s.size {
			from = s.size
		}
		if s.size <= from {
			continue
		}
		ok, err := fileHasByteFrom(filepath.Join(dir, s.name), from, '\n')
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}
	return false, nil
}

// journalScanStart is the first byte a drain check should inspect.
// A missing offset segment keeps that name so older survivors stay
// skipped, matching ReadJournalFrom.
func journalScanStart(segs []journalSegment, offset JournalOffset) (string, int64) {
	if offset.Segment == "" {
		return "", 0
	}
	for _, s := range segs {
		if s.name == offset.Segment {
			return offset.Segment, offset.Byte
		}
	}
	return offset.Segment, 0
}

func fileHasByteFrom(path string, from int64, needle byte) (bool, error) {
	f, err := os.Open(path) // #nosec G304 -- path derived from state dir
	if err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, fmt.Errorf("journal: open %s: %w", filepath.Base(path), err)
	}
	defer f.Close()
	if from > 0 {
		if _, err := f.Seek(from, io.SeekStart); err != nil {
			return false, fmt.Errorf("journal: seek %s: %w", filepath.Base(path), err)
		}
	}
	buf := make([]byte, 4096)
	for {
		n, err := f.Read(buf)
		if n > 0 && bytes.IndexByte(buf[:n], needle) >= 0 {
			return true, nil
		}
		if err == io.EOF || (err == nil && n == 0) {
			return false, nil
		}
		if err != nil {
			return false, fmt.Errorf("journal: read %s: %w", filepath.Base(path), err)
		}
	}
}

func journalCursor(offset JournalOffset) store.JournalCursor {
	return store.JournalCursor{Segment: offset.Segment, Byte: offset.Byte}
}

func journalOffset(cursor store.JournalCursor) JournalOffset {
	return JournalOffset{Segment: cursor.Segment, Byte: cursor.Byte}
}

func flagCorrectionSightings(pairs []flagCorrection) ([]store.FlagCorrectionSighting, error) {
	items := make([]store.FlagCorrectionSighting, 0, len(pairs))
	for _, p := range pairs {
		payload, err := json.Marshal(flagAliasDerivedPayload{
			CommandPath:   p.CommandPath,
			FailedFlag:    p.FailedFlag,
			CorrectedFlag: p.CorrectedFlag,
			Example:       p.Example,
		})
		if err != nil {
			return nil, fmt.Errorf("derive flag corrections: marshal payload: %w", err)
		}
		items = append(items, store.FlagCorrectionSighting{
			Class:       store.CandidateClassFlagAlias,
			Payload:     string(payload),
			Signature:   flagCorrectionSignature(p.CommandPath, p.FailedFlag, p.CorrectedFlag),
			QueryFamily: p.QueryFamily,
			CommandPath: p.CommandPath,
		})
	}
	return items, nil
}

// flagCorrectionSignature is the stable derivation signature for a
// flag correction: the class plus its three identity fields, joined so
// the same correction observed again converges on one candidate row.
func flagCorrectionSignature(commandPath, failedFlag, correctedFlag string) string {
	return strings.Join([]string{store.CandidateClassFlagAlias, commandPath, failedFlag, correctedFlag}, "|")
}

// pairFlagCorrections walks the batch in order applying the pairing
// rule, and reports whether any unpaired failure is still fresh enough
// that its correction may yet arrive (the caller then holds the whole
// batch).
func pairFlagCorrections(entries []JournalEntry, recallSeed map[string]string, now time.Time, flagExists func(name string) bool) ([]flagCorrection, bool) {
	var pairs []flagCorrection
	pending := false
	// The family anchor for a derived candidate is the family of the
	// session's most recent recall entry. Seed from the full-journal
	// scan (recall entries commonly predate the batch), then let any
	// fresher in-batch recall override it as the walk proceeds.
	lastRecallFamily := map[string]string{}
	for k, v := range recallSeed {
		lastRecallFamily[k] = v
	}
	for i := range entries {
		e := entries[i]
		if len(e.Cmd) > 0 && e.Cmd[0] == "recall" && e.QueryFamily != "" {
			lastRecallFamily[e.SessionKey] = e.QueryFamily
		}
		if e.ExitCode == 0 || e.FailedFlag == "" {
			continue
		}
		failed := normalizeFlagToken(e.FailedFlag)
		if failed == "" {
			continue
		}
		if flagExists != nil && flagExists(strings.TrimLeft(failed, "-")) {
			// A real flag somewhere in the tree (even on a sibling
			// command) is a usage error, not a healable alias.
			continue
		}
		failedAt, ok := parseJournalTime(e.TS)
		if !ok {
			continue
		}
		// The NEXT invocation of the same command in the same session
		// decides the pairing; a later success never reaches back past
		// an intervening retry.
		nextIdx := -1
		for j := i + 1; j < len(entries); j++ {
			if entries[j].SessionKey == e.SessionKey && sameVerbChain(entries[j].Cmd, e.Cmd) {
				nextIdx = j
				break
			}
		}
		if nextIdx < 0 {
			if now.Sub(failedAt) <= flagCorrectionWindow {
				pending = true
			}
			continue
		}
		success := entries[nextIdx]
		if success.ExitCode != 0 {
			continue
		}
		succeededAt, ok := parseJournalTime(success.TS)
		if !ok || succeededAt.Before(failedAt) || succeededAt.Sub(failedAt) > flagCorrectionWindow {
			continue
		}
		corrected := correctedFlagForPair(e, success)
		if corrected == "" || corrected == failed {
			continue
		}
		pairs = append(pairs, flagCorrection{
			CommandPath:   strings.Join(e.Cmd, " "),
			FailedFlag:    failed,
			CorrectedFlag: corrected,
			Example:       sanitizedInvocationExample(success),
			QueryFamily:   lastRecallFamily[e.SessionKey],
		})
	}
	return pairs, pending
}

// correctedFlagForPair chooses the correction for one decided
// failure/success pair. Cobra's did-you-mean suggestion remains the
// strongest signal; when Cobra had no suggestion, infer from the new
// flag name introduced by the successful retry. Ambiguous deltas return
// empty so derivation records no candidate.
func correctedFlagForPair(failed, success JournalEntry) string {
	suggested := normalizeFlagToken(failed.SuggestedFlag)
	if suggested != "" {
		if _, present := success.ArgvShape[strings.TrimLeft(suggested, "-")]; present {
			return suggested
		}
		return ""
	}
	return inferCorrectedFlagFromNewSuccessFlag(failed, success)
}

func inferCorrectedFlagFromNewSuccessFlag(failed, success JournalEntry) string {
	failedName := strings.TrimLeft(normalizeFlagToken(failed.FailedFlag), "-")
	if failedName == "" {
		return ""
	}
	failedShape := make(map[string]struct{}, len(failed.ArgvShape))
	for name := range failed.ArgvShape {
		name = strings.TrimLeft(normalizeFlagToken(name), "-")
		if name != "" {
			failedShape[name] = struct{}{}
		}
	}
	bestName := ""
	bestDistance := 0
	ambiguous := false
	for name := range success.ArgvShape {
		name = strings.TrimLeft(normalizeFlagToken(name), "-")
		if name == "" {
			continue
		}
		if _, alreadyPresent := failedShape[name]; alreadyPresent {
			continue
		}
		distance := editDistance(failedName, name)
		if bestName == "" || distance < bestDistance {
			bestName = name
			bestDistance = distance
			ambiguous = false
			continue
		}
		if distance == bestDistance {
			ambiguous = true
		}
	}
	// Cap the inferred correction to a meaningful edit distance. An
	// unrelated new success flag (e.g. --sport when --date failed) must
	// not be promoted as a correction: distance beyond half the shorter
	// name's length means the two share no meaningful overlap.
	if bestName != "" {
		maxDistance := min(len([]rune(failedName)), len([]rune(bestName))) / 2
		if maxDistance < 1 {
			maxDistance = 1
		}
		if bestDistance > maxDistance {
			return ""
		}
	}
	if bestName == "" || ambiguous {
		return ""
	}
	return "--" + bestName
}

// sessionRecallFamiliesBeforeBatch returns, for sessions touched by the
// current batch, the most recent recall family before the persisted offset.
// Best-effort: read errors yield no seed and derivation still proceeds.
func sessionRecallFamiliesBeforeBatch(batch []JournalEntry, offset JournalOffset) map[string]string {
	if offset.Segment == "" && offset.Byte == 0 {
		return map[string]string{}
	}
	active := make(map[string]struct{}, 4)
	for _, e := range batch {
		if e.SessionKey != "" {
			active[e.SessionKey] = struct{}{}
		}
	}
	if len(active) == 0 {
		return map[string]string{}
	}
	dir, err := JournalDir()
	if err != nil {
		return map[string]string{}
	}
	segs, err := listJournalSegments(dir)
	if err != nil {
		return map[string]string{}
	}
	families := make(map[string]string, 4)
	for i := len(segs) - 1; i >= 0 && len(families) < len(active); i-- {
		seg := segs[i]
		if offset.Segment != "" && seg.name > offset.Segment {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, seg.name)) // #nosec G304 -- listed from state dir
		if err != nil {
			continue
		}
		if seg.name == offset.Segment && offset.Byte < int64(len(data)) {
			data = data[:offset.Byte]
		}
		scanRecallFamiliesReverse(data, active, families)
	}
	return families
}

func scanRecallFamiliesReverse(data []byte, active map[string]struct{}, families map[string]string) {
	lines := bytes.Split(data, []byte{'\n'})
	for i := len(lines) - 1; i >= 0 && len(families) < len(active); i-- {
		line := lines[i]
		if len(line) == 0 || line[0] != '{' {
			continue
		}
		var e JournalEntry
		if err := json.Unmarshal(line, &e); err != nil {
			continue
		}
		if _, ok := active[e.SessionKey]; !ok {
			continue
		}
		if _, seen := families[e.SessionKey]; seen {
			continue
		}
		if len(e.Cmd) > 0 && e.Cmd[0] == "recall" && e.QueryFamily != "" {
			families[e.SessionKey] = e.QueryFamily
		}
	}
}

// sanitizedInvocationExample renders a journal entry as a replayable
// shape hint: the verb chain plus sorted flag names. Flag values never
// appear (the journal never recorded them) and neither do positionals.
func sanitizedInvocationExample(e JournalEntry) string {
	parts := append([]string(nil), e.Cmd...)
	names := make([]string, 0, len(e.ArgvShape))
	for name := range e.ArgvShape {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		parts = append(parts, "--"+name)
	}
	return strings.Join(parts, " ")
}

// normalizeFlagToken canonicalizes a journaled flag reference to its
// double-dash form so signatures and payloads stay byte-stable however
// the source error message spelled it.
func normalizeFlagToken(tok string) string {
	tok = strings.TrimSpace(tok)
	name := strings.TrimLeft(tok, "-")
	if name == "" {
		return ""
	}
	return "--" + name
}

func editDistance(a, b string) int {
	ar := []rune(a)
	br := []rune(b)
	prev := make([]int, len(br)+1)
	for j := range prev {
		prev[j] = j
	}
	for i, ra := range ar {
		curr := make([]int, len(br)+1)
		curr[0] = i + 1
		for j, rb := range br {
			cost := 0
			if ra != rb {
				cost = 1
			}
			del := prev[j+1] + 1
			ins := curr[j] + 1
			sub := prev[j] + cost
			curr[j+1] = del
			if ins < curr[j+1] {
				curr[j+1] = ins
			}
			if sub < curr[j+1] {
				curr[j+1] = sub
			}
		}
		prev = curr
	}
	return prev[len(br)]
}

func sameVerbChain(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func parseJournalTime(ts string) (time.Time, bool) {
	t, err := time.Parse(time.RFC3339, ts)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}
